def _square_schedule(m,k,n):
    if m==n:
        depth=_SQUARE_EQUAL_DEPTHS[m//32-1][k//32-1]
    elif (m==k and n==1024) or (k==n and m==1024):
        depth=_SQUARE_CROSS_DEPTHS[k//32-1]
